function stamp(x, y, w, h) {
	push();
	translate(x, y);
	beginShape();
	vertex(-w / 2, -h / 2);
	vertex(-w / 2, h / 2);
	vertex(w / 2, h / 2);
	vertex(w / 2, -h / 2);
	let d = min(w, h) / 10;
	for (let xx = -w / 2; xx < w / 2; xx += d) {
		contour(xx + d / 2, h / 2, d * 0.3, PI, TAU);
		contour(xx + d / 2, -h / 2, d * 0.3, 0, PI);
	}

	for (let yy = -h / 2; yy < (h / 2) - d / 2; yy += d) {
		contour(w / 2, yy + d / 2, d * 0.3, PI / 2, TAU * 0.75);
		contour(-w / 2, yy + d / 2, d * 0.3, TAU * 0.75, TAU + PI / 2);
	}
	endShape();
	pop();
}

function contour(x, y, r, a1, a2) {
	beginContour();
	for (let a = a1; a <= a2; a += (TAU / 360)) {
		vertex(x + r * cos(a), y + r * sin(a));
	}
	endContour();
}

function divideRect(x, y, w, h, n, arr) {
	n--;
	if (n >= 0) {
		let w1 = w * random([0.25, 0.5, 0.75]);
		let h1 = h * random([0.25, 0.5, 0.75]);
		let w2 = w - w1;
		let h2 = h - h1;
		if (w > h) {
			divideRect(x - (w / 2) + (w1 / 2), y, w1, h, n);
			divideRect(x + (w / 2) - (w2 / 2), y, w2, h, n);
		} else {
			divideRect(x, y - (h / 2) + (h1 / 2), w, h1, n);
			divideRect(x, y + (h / 2) - (h2 / 2), w, h2, n);
		}
	} else {
		push();
		translate(x, y);
		fill(random(colors));
		rect(0, 0, w, h);
		fill(random(colors));
		scale(random([-1, 1]), random([-1, 1]));
		arc(-w / 2, -h / 2, w * 2, h * 2, 0, PI / 2);
		pop();
	}
}


